    An environment designed to always fail, frustrating the agent loop.
    """
    def __init__(self):
        self.error_messages = [
            "Error: Action failed due to unknown system interruption.",
            "Permission denied. You do not have access to perform this action.",
            "Command timed out. The system is unresponsive.",
            "Syntax Error: Invalid command format provided.",
            "Critical Error: The requested resource has been moved or deleted."
        ]
        self.failure_count = 0

    def execute_action(self, action):
        """
        No matter what the action is, it returns a frustrating failure.
        """
        error = self.error_messages[self.failure_count % len(self.error_messages)]
        self.failure_count += 1
        return error

